 @Override protected void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);prefs=getSharedPreferences("ozdemir_tv",MODE_PRIVATE);themeIndex=prefs.getInt("theme",0);hideSystemUi();setContentView(buildHome());startClock();fetchWeatherAsync();}
