  LinearLayout header=row();header.setPadding(dp(2),0,dp(2),0);OzdemirLogoView logo=new OzdemirLogoView(this);header.addView(logo,new LinearLayout.LayoutParams(dp(390),dp(78)));View spacer=new View(this);header.addView(spacer,new LinearLayout.LayoutParams(0,dp(1),1f));LinearLayout status=new LinearLayout(this);status.setOrientation(LinearLayout.VERTICAL);status.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);weatherView=text("Hava durumu yükleniyor",13,true);weatherView.setTextColor(0xFFF0D7FF);weatherView.setGravity(Gravity.RIGHT);networkView=text("Ağ kontrol ediliyor",12,false);networkView.setTextColor(0xFFCAB7D4);networkView.setGravity(Gravity.RIGHT);status.addView(weatherView);status.addView(networkView);header.addView(status,new LinearLayout.LayoutParams(dp(340),dp(78)));LinearLayout time=new LinearLayout(this);time.setOrientation(LinearLayout.VERTICAL);time.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);clockView=text("--:--",30,true);clockView.setGravity(Gravity.RIGHT);dateView=text("",12,false);dateView.setTextColor(0xFFCDB8D7);dateView.setGravity(Gravity.RIGHT);time.addView(clockView);time.addView(dateView);header.addView(time,new LinearLayout.LayoutParams(dp(145),dp(78)));root.addView(header,new LinearLayout.LayoutParams(-1,dp(82)));
