 private View heroCard(String icon,String title,String sub,Runnable action){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(24),dp(18),dp(20),dp(16));box.setFocusable(true);box.setFocusableInTouchMode(true);box.setClickable(true);box.setBackground(heroBackground(false));box.setElevation(dp(3));TextView i=text(icon,28,true);i.setTextColor(0xFFE8C7FF);box.addView(i);TextView t=text(title,22,true);t.setPadding(0,dp(10),0,0);box.addView(t);TextView s=text(sub,12,false);s.setTextColor(0xFFC9B7D0);s.setPadding(0,dp(6),0,0);s.setSingleLine(true);box.addView(s);box.setOnClickListener(v->action.run());box.setOnFocusChangeListener((v,f)->{v.animate().scaleX(f?1.055f:1f).scaleY(f?1.055f:1f).translationY(f?-dp(3):0).setDuration(130).start();v.setBackground(heroBackground(f));v.setElevation(f?dp(18):dp(3));i.setTextColor(f?Color.WHITE:0xFFE8C7FF);});return box;}
 private View kidCard(String icon,String title,int style,Runnable action){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(12),dp(9),dp(12),dp(9));box.setFocusable(true);box.setFocusableInTouchMode(true);box.setClickable(true);box.setBackground(kidBackground(style,false));box.setElevation(dp(2));TextView i=text(icon,21,true);i.setGravity(Gravity.CENTER);i.setTextColor(0xFFFFF3FF);box.addView(i);TextView t=text(title,14,true);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(5),0,0);t.setSingleLine(true);box.addView(t);box.setOnClickListener(v->action.run());box.setOnFocusChangeListener((v,f)->{v.animate().scaleX(f?1.07f:1f).scaleY(f?1.07f:1f).translationY(f?-dp(2):0).setDuration(120).start();v.setBackground(kidBackground(style,f));v.setElevation(f?dp(14):dp(2));});return box;}
 private View systemCard(String icon,String title,Runnable action){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(10),dp(8),dp(10),dp(8));box.setFocusable(true);box.setFocusableInTouchMode(true);box.setClickable(true);box.setBackground(systemBackground(false));box.setElevation(dp(1));TextView i=text(icon,19,true);i.setGravity(Gravity.CENTER);i.setTextColor(0xFFDCC7E8);box.addView(i);TextView t=text(title,13,true);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(5),0,0);t.setSingleLine(true);box.addView(t);box.setOnClickListener(v->action.run());box.setOnFocusChangeListener((v,f)->{v.animate().scaleX(f?1.06f:1f).scaleY(f?1.06f:1f).translationY(f?-dp(2):0).setDuration(110).start();v.setBackground(systemBackground(f));v.setElevation(f?dp(12):dp(1));i.setTextColor(f?Color.WHITE:0xFFDCC7E8);});return box;}
 private GradientDrawable systemBackground(boolean f){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,f?new int[]{0xEE672C8C,0xEE3B1B5B}:new int[]{0xC0251930,0xB2181220});d.setCornerRadius(dp(15));d.setStroke(dp(f?2:1),f?0xFFF0D8FF:0x66583D67);return d;}
 private GradientDrawable kidBackground(int style,boolean f){int[][] normal={{0xE1481F68,0xD92A133E},{0xE1352B72,0xD91D1946},{0xE1234075,0xD914294D},{0xE2672555,0xD93D1836},{0xE2522B69,0xD92B1942},{0xE3382953,0xD91F1832}};int[][] focused={{0xFFBD3E95,0xFF711F78},{0xFF675BDC,0xFF3B3296},{0xFF3994DA,0xFF245A9E},{0xFFD74E87,0xFF852C5C},{0xFF975DD8,0xFF5D378D},{0xFF7A61B8,0xFF473673}};GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,f?focused[style]:normal[style]);d.setCornerRadius(dp(19));d.setStroke(dp(f?2:1),f?0xFFFFFFFF:0x667D5B86);return d;}
