 private void applyTheme(){if(root==null)return;root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,themes[themeIndex]));}private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}private LinearLayout.LayoutParams weightCard(int h,int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1f);p.setMargins(dp(h),dp(v),dp(h),dp(v));return p;}private TextView section(String s){TextView t=text(s,15,true);t.setTextColor(0xFFE4C5F3);t.setGravity(Gravity.BOTTOM|Gravity.LEFT);t.setPadding(dp(8),dp(6),0,0);t.setLetterSpacing(.03f);return t;}private TextView text(String s,int sp,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xFFF8F3FA);t.setTextSize(sp);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 private void openPanel(String page){Intent i=new Intent(this,SettingsPanelActivity.class);i.putExtra("page",page);startActivity(i);}private void openLiveTv(){startActivity(new Intent(this,LiveTvActivity.class));}private void openDiziFilm(){startActivity(new Intent(this,DiziFilmActivity.class));}private void openKids(){startActivity(new Intent(this,KidsActivity.class));}private void openApps(){startActivity(new Intent(this,AppsActivity.class));}private void openFiles(){startActivity(new Intent(this,FilesActivity.class));}private void launchFirst(String[] p,String m){for(String x:p){Intent i=getPackageManager().getLaunchIntentForPackage(x);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);return;}}missing(m);}private void openSettings(String a){if(Settings.ACTION_WIFI_SETTINGS.equals(a)){openPanel("network");return;}if(Settings.ACTION_INTERNAL_STORAGE_SETTINGS.equals(a)){openPanel("storage");return;}if(Settings.ACTION_SETTINGS.equals(a)){openPanel("settings");return;}try{startActivity(new Intent(a));}catch(Exception e){openPanel("settings");}}private void missing(String m){Toast.makeText(this,m,Toast.LENGTH_SHORT).show();}
 private void startClock(){clockHandler.post(new Runnable(){@Override public void run(){Date n=new Date();if(clockView!=null)clockView.setText(new SimpleDateFormat("HH:mm",new Locale("tr","TR")).format(n));if(dateView!=null)dateView.setText(new SimpleDateFormat("d MMM EEE",new Locale("tr","TR")).format(n));updateNetwork();if(System.currentTimeMillis()-lastWeather>15*60*1000)fetchWeatherAsync();clockHandler.postDelayed(this,15000);}});}private void updateNetwork(){if(networkView==null)return;boolean o=false;try{ConnectivityManager cm=(ConnectivityManager)getSystemService(Context.CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities c=n==null?null:cm.getNetworkCapabilities(n);o=c!=null&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);}catch(Exception ignored){}networkView.setText(o?"● Wi‑Fi / İnternet bağlı":"○ Çevrimdışı");networkView.setTextColor(o?0xFFE5CFF3:0xFFB0A5B8);}
 private void fetchWeatherAsync(){lastWeather=System.currentTimeMillis();new Thread(()->{HttpURLConnection h=null;try{h=(HttpURLConnection)new URL("https://wttr.in/?format=j1").openConnection();h.setConnectTimeout(4000);h.setReadTimeout(5000);h.setRequestProperty("User-Agent","OZDEMIR-TV-OS");BufferedReader r=new BufferedReader(new InputStreamReader(h.getInputStream(),"UTF-8"));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null)b.append(line);r.close();JSONObject root=new JSONObject(b.toString());if(root.has("data"))root=root.getJSONObject("data");JSONArray cc=root.getJSONArray("current_condition");JSONObject c=cc.getJSONObject(0);String temp=c.optString("temp_C","--");String desc="";JSONArray d=c.optJSONArray("weatherDesc");if(d!=null&&d.length()>0)desc=d.getJSONObject(0).optString("value","");JSONObject req=root.optJSONArray("request")!=null&&root.getJSONArray("request").length()>0?root.getJSONArray("request").getJSONObject(0):null;String loc=req==null?"":req.optString("query","");String txt=(loc.isEmpty()?"":loc+" • ")+temp+"°C"+(desc.isEmpty()?"":" • "+desc);runOnUiThread(()->{if(weatherView!=null)weatherView.setText(txt);});}catch(Exception e){runOnUiThread(()->{if(weatherView!=null)weatherView.setText("Hava durumu kullanılamıyor");});}finally{if(h!=null)h.disconnect();}}).start();}
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
